-- content-upgrade:pretoria:fixes (not generated by to-sql.mjs, same guard pattern)

-- Dr H Jocum: address precision fix (house number added)
UPDATE businesses SET address = '102 Herbert Baker Street, Groenkloof, Pretoria, 0181'
WHERE slug = 'dr-h-jocum-waterkloof'
  AND address = 'Herbert Baker Street'
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id);

-- KEB Centurion: owner-confirmed category fix, Industrial Suppliers & Manufacturing -> Liquor Stores (beverage distributor)
UPDATE business_categories SET category_id = (SELECT id FROM categories WHERE slug = 'liquor-stores')
WHERE business_id = (SELECT id FROM businesses WHERE slug = 'keb-centurion-eco-park' AND owner_user_id IS NULL)
  AND is_primary = 1
  AND category_id = (SELECT id FROM categories WHERE slug = 'industrial-suppliers-manufacturing')
  AND (SELECT id FROM categories WHERE slug = 'liquor-stores') IS NOT NULL;
